module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic in,
    output logic done
);

    typedef enum logic [3:0] {
        S_IDLE      = 4'd0,
        S_B0        = 4'd1,
        S_B1        = 4'd2,
        S_B2        = 4'd3,
        S_B3        = 4'd4,
        S_B4        = 4'd5,
        S_B5        = 4'd6,
        S_B6        = 4'd7,
        S_B7        = 4'd8,
        S_STOP      = 4'd9,
        S_WAIT_STOP = 4'd10
    } state_t;

    state_t state, next_state;
    logic [7:0] shift_reg;

    always_ff @(posedge clk) begin
        if (reset) begin
            state     <= S_IDLE;
            shift_reg <= 8'd0;
            done      <= 1'b0;
        end else begin
            state <= next_state;
            done  <= 1'b0;

            case (next_state)
                S_B0: shift_reg[0] <= in;
                S_B1: shift_reg[1] <= in;
                S_B2: shift_reg[2] <= in;
                S_B3: shift_reg[3] <= in;
                S_B4: shift_reg[4] <= in;
                S_B5: shift_reg[5] <= in;
                S_B6: shift_reg[6] <= in;
                S_B7: shift_reg[7] <= in;
                default: ;
            endcase

            if (state == S_STOP && in == 1'b1) begin
                done <= 1'b1;
            end
        end
    end

    always_comb begin
        next_state = state;

        case (state)
            S_IDLE: begin
                if (in == 1'b0) begin
                    next_state = S_B0;
                end
            end
            S_B0: next_state = S_B1;
            S_B1: next_state = S_B2;
            S_B2: next_state = S_B3;
            S_B3: next_state = S_B4;
            S_B4: next_state = S_B5;
            S_B5: next_state = S_B6;
            S_B6: next_state = S_B7;
            S_B7: next_state = S_STOP;
            S_STOP: begin
                if (in == 1'b1) begin
                    next_state = S_IDLE;
                end else begin
                    next_state = S_WAIT_STOP;
                end
            end
            S_WAIT_STOP: begin
                if (in == 1'b1) begin
                    next_state = S_IDLE;
                end else begin
                    next_state = S_WAIT_STOP;
                end
            end
            default: next_state = S_IDLE;
        endcase
    end

endmodule

