module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic in,
    output logic done
);

    typedef enum logic [1:0] {
        S_IDLE      = 2'd0,
        S_DATA      = 2'd1,
        S_STOP      = 2'd2,
        S_WAIT_STOP = 2'd3
    } state_t;

    state_t state, next_state;
    logic [2:0] bit_cnt;
    logic [7:0] shift_reg;

    always_ff @(posedge clk) begin
        if (reset) begin
            state     <= S_IDLE;
            bit_cnt   <= 3'd0;
            shift_reg <= 8'd0;
        end else begin
            state <= next_state;

            case (state)
                S_IDLE: begin
                    if (in == 1'b0) begin
                        bit_cnt <= 3'd0;
                    end
                end
                S_DATA: begin
                    shift_reg <= {in, shift_reg[7:1]};
                    if (bit_cnt < 3'd7) begin
                        bit_cnt <= bit_cnt + 1'b1;
                    end
                end
                default: ;
            endcase
        end
    end

    always_comb begin
        next_state = state;
        done       = 1'b0;

        case (state)
            S_IDLE: begin
                if (in == 1'b0) begin
                    next_state = S_DATA;
                end
            end
            S_DATA: begin
                if (bit_cnt == 3'd7) begin
                    next_state = S_STOP;
                end else begin
                    next_state = S_DATA;
                end
            end
            S_STOP: begin
                if (in == 1'b1) begin
                    done       = 1'b1;
                    next_state = S_IDLE;
                end else begin
                    next_state = S_WAIT_STOP;
                end
            end
            S_WAIT_STOP: begin
                if (in == 1'b1) begin
                    next_state = S_IDLE;
                end else begin
                    next_state = S_WAIT_STOP;
                end
            end
            default: begin
                next_state = S_IDLE;
            end
        endcase
    end

endmodule

